import { createFileRoute } from '@tanstack/react-router';
import { SanctuaryShell } from '../../../../app/(sanctuary)/components/SanctuaryShell';
import { DocumentReaderDesk } from '../../../../app/(sanctuary)/library/reader/[bookId]/DocumentReaderDesk';

// Generated by scripts/codemods/web-migrate.mjs from the explore branch of app/(sanctuary)/library/reader/[bookId]/page.tsx,
// decided at build time instead of per request. Edit freely; the codemod never overwrites it.
export const Route = createFileRoute('/library/reader/$bookId')({
  component: ExploreRoute,
});

function ExploreRoute() {
  const { bookId } = Route.useParams();
  return (
    <SanctuaryShell
      displayName="Guest Explorer"
      navigationPrefix=""
      showAccountNavigation={true}
      isExploreMode={true}
    >
      <DocumentReaderDesk bookId={bookId} displayName="Guest Explorer" />
    </SanctuaryShell>
  );
}
